// src/components/ValidationAffectations.jsx
import { useState, useEffect } from "react";
import { affectationApi } from "../api/api";

const BADGE = {
  EN_ATTENTE: { label: "En attente", style: { background: "#FEF3C7", color: "#92400E", border: "1px solid #D97706" } },
  VALIDEE:    { label: "Validée",    style: { background: "#D1FAE5", color: "#065F46", border: "1px solid #059669" } },
  REFUSEE:    { label: "Refusée",    style: { background: "#FEE2E2", color: "#991B1B", border: "1px solid #DC2626" } },
};

function Badge({ statut }) {
  const b = BADGE[statut] || BADGE.EN_ATTENTE;
  return (
    <span style={{ ...b.style, padding: "2px 10px", borderRadius: 12, fontSize: 12, fontWeight: 600 }}>
      {b.label}
    </span>
  );
}

export default function ValidationAffectations() {
  const [affectations, setAffectations] = useState([]);
  const [loading, setLoading]           = useState(true);
  const [error, setError]               = useState(null);
  const [commentaire, setCommentaire]   = useState({});
  const [filter, setFilter]             = useState("EN_ATTENTE");

  const load = async () => {
    setLoading(true);
    try {
      const data = await affectationApi.getAll();
      setAffectations(data);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const handleValider = async (id) => {
    try {
      await affectationApi.valider(id);
      await load();
    } catch (e) { alert(e.message); }
  };

  const handleRefuser = async (id) => {
    const c = commentaire[id];
    if (!c?.trim()) { alert("Commentaire obligatoire pour refuser."); return; }
    try {
      await affectationApi.refuser(id, c);
      await load();
    } catch (e) { alert(e.message); }
  };

  const handleValiderToutes = async () => {
    if (!window.confirm("Valider toutes les affectations en attente ?")) return;
    try {
      const res = await affectationApi.validerToutes();
      alert(`${res.validees} affectation(s) validée(s).`);
      await load();
    } catch (e) { alert(e.message); }
  };

  const filtered = affectations.filter(a =>
    filter === "TOUT" ? true : a.statut === filter
  );

  const counts = {
    EN_ATTENTE: affectations.filter(a => a.statut === "EN_ATTENTE").length,
    VALIDEE:    affectations.filter(a => a.statut === "VALIDEE").length,
    REFUSEE:    affectations.filter(a => a.statut === "REFUSEE").length,
  };

  if (loading) return <div style={styles.center}>Chargement...</div>;
  if (error)   return <div style={{ ...styles.center, color: "red" }}>{error}</div>;

  return (
    <div style={styles.page}>
      <h2 style={styles.title}>Phase 1 — Validation des affectations</h2>

      {/* Métriques */}
      <div style={styles.metrics}>
        {[
          { label: "En attente", val: counts.EN_ATTENTE, color: "#F59E0B" },
          { label: "Validées",   val: counts.VALIDEE,    color: "#10B981" },
          { label: "Refusées",   val: counts.REFUSEE,    color: "#EF4444" },
          { label: "Total",      val: affectations.length, color: "#6366F1" },
        ].map(m => (
          <div key={m.label} style={styles.metric}>
            <div style={{ fontSize: 28, fontWeight: 700, color: m.color }}>{m.val}</div>
            <div style={{ fontSize: 13, color: "#6B7280" }}>{m.label}</div>
          </div>
        ))}
      </div>

      {/* Filtres */}
      <div style={styles.filters}>
        {["EN_ATTENTE", "VALIDEE", "REFUSEE", "TOUT"].map(f => (
          <button key={f} onClick={() => setFilter(f)}
            style={{ ...styles.filterBtn, ...(filter === f ? styles.filterActive : {}) }}>
            {f === "TOUT" ? "Toutes" : BADGE[f]?.label}
          </button>
        ))}
        {counts.EN_ATTENTE > 0 && (
          <button onClick={handleValiderToutes} style={styles.btnAll}>
            Valider toutes en attente ({counts.EN_ATTENTE})
          </button>
        )}
      </div>

      {/* Liste */}
      {filtered.length === 0 && (
        <div style={styles.empty}>Aucune affectation dans cette catégorie.</div>
      )}

      {filtered.map(a => (
        <div key={a.id} style={styles.card}>
          <div style={styles.cardHeader}>
            <div>
              <div style={styles.cardTitle}>
                {a.binome?.etudiant1?.nom} & {a.binome?.etudiant2?.nom}
              </div>
              <div style={styles.cardSub}>
                Moyenne binôme : {a.binome?.moyenneBinome?.toFixed(1)} / 20
              </div>
            </div>
            <Badge statut={a.statut} />
          </div>

          <div style={styles.row}>
            <span style={styles.rowLabel}>Sujet</span>
            <span style={styles.rowVal}>{a.sujet?.titre}</span>
          </div>
          <div style={styles.row}>
            <span style={styles.rowLabel}>Encadrant</span>
            <span style={styles.rowVal}>{a.sujet?.encadrant?.nom}</span>
          </div>
          <div style={styles.row}>
            <span style={styles.rowLabel}>Score</span>
            <span style={styles.rowVal}>{a.score?.toFixed(1)} pts</span>
          </div>

          {/* Actions — seulement si pas verrouillée */}
          {!a.verrouillee && (
            <div style={styles.actions}>
              <button onClick={() => handleValider(a.id)} style={styles.btnOk}>
                Valider
              </button>
              <div style={{ display: "flex", gap: 8, flex: 1 }}>
                <input
                  placeholder="Commentaire (obligatoire pour refuser)"
                  value={commentaire[a.id] || ""}
                  onChange={e => setCommentaire(p => ({ ...p, [a.id]: e.target.value }))}
                  style={styles.input}
                />
                <button onClick={() => handleRefuser(a.id)} style={styles.btnNo}>
                  Refuser
                </button>
              </div>
            </div>
          )}

          {a.verrouillee && (
            <div style={styles.locked}>
              Affectation verrouillée — aucune modification possible
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

const styles = {
  page:        { maxWidth: 800, margin: "0 auto", padding: "24px 16px", fontFamily: "sans-serif" },
  title:       { fontSize: 22, fontWeight: 700, color: "#111827", marginBottom: 20 },
  center:      { textAlign: "center", padding: 40, color: "#6B7280" },
  metrics:     { display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 12, marginBottom: 20 },
